// Phase 9 · the OTP corpus shared by apps/web/src/lib/sms/secret.test.ts and (generated by
// scripts/secret-sql-test.mjs) supabase/tests/database/sms_secret.test.sql. Add a case here, then
// run `node --experimental-strip-types scripts/secret-sql-test.mjs`.

export const digits = (zero: number, s: string) =>
  [...s].map((d) => String.fromCodePoint(zero + Number(d))).join('');

